import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";var i=JSON.parse(`{"title":"Vibe Coding 的未来与风险","description":"当\\"用嘴编程\\"成为现实，工程师的价值锚点会从写代码转向哪里？聊聊 Vibe Coding 的想象空间与真实风险。","frontmatter":{"title":"Vibe Coding 的未来与风险","date":"2026-06-20T00:00:00.000Z","tags":["AI","编程"],"category":"随笔","description":"当\\"用嘴编程\\"成为现实，工程师的价值锚点会从写代码转向哪里？聊聊 Vibe Coding 的想象空间与真实风险。"},"headers":[],"relativePath":"articles/note/vibe-coding-future-and-risk.md","filePath":"articles/note/vibe-coding-future-and-risk.md","articleMeta":{"updated":"2026-06-20","words":372,"minutes":1}}`),a={name:`articles/note/vibe-coding-future-and-risk.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p>&quot;Vibe Coding&quot; 指的是完全依靠自然语言描述需求、由 AI 生成代码的开发方式。它正在从梗变成一种真实的工作流。</p><h2 id="想象空间" tabindex="-1">想象空间 <a class="header-anchor" href="#想象空间" aria-label="Permalink to “想象空间”">​</a></h2><ul><li><strong>门槛消失</strong>：不会写代码的人也能做出能用的产品原型</li><li><strong>速度飞跃</strong>：从想法到可运行 demo 的周期从周缩短到小时</li><li><strong>角色迁移</strong>：工程师从&quot;实现者&quot;变成&quot;需求定义者 + 审校者&quot;</li></ul><h2 id="真实风险" tabindex="-1">真实风险 <a class="header-anchor" href="#真实风险" aria-label="Permalink to “真实风险”">​</a></h2><ol><li><strong>理解断层</strong>：生成的代码没人真正读懂，出问题时无从下手</li><li><strong>安全隐患</strong>：AI 生成的代码可能包含不安全的默认实现</li><li><strong>技术债黑洞</strong>：快速堆出来的功能，长期维护成本极高</li><li><strong>能力退化</strong>：过度依赖生成，基础功可能逐渐荒废</li></ol><h2 id="我的看法" tabindex="-1">我的看法 <a class="header-anchor" href="#我的看法" aria-label="Permalink to “我的看法”">​</a></h2><p>Vibe Coding 适合原型验证与一次性脚本，不适合核心业务系统。未来工程师的核心竞争力是：<strong>判断力</strong>——知道 AI 给的东西哪里对、哪里不对。</p><p>工具在变，工程思维的底层逻辑不变。</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};